<script setup lang="ts">
import { shallowRef } from 'vue'
import { checkApplicationUpdate } from '../services/platform'
const update = shallowRef('尚未检查'); const actionLabel = shallowRef(''); const updateAction = shallowRef<null | (() => Promise<void>)>(null)
async function checkUpdate(){ try { const result=await checkApplicationUpdate(); update.value=result.message; actionLabel.value=result.actionLabel ?? ''; updateAction.value=result.action ?? null } catch { update.value='更新检查失败，请稍后重试。'; actionLabel.value=''; updateAction.value=null } }
async function runUpdateAction(){ if(!updateAction.value) return; try { update.value=actionLabel.value==='下载并安装'?'正在下载并验证签名…':'正在打开下载页…'; await updateAction.value(); if(actionLabel.value==='下载并安装') update.value='更新已完成，应用将按系统提示重启。' } catch { update.value='操作失败，请稍后重试。' } }
</script>
<template><div class="view"><header><p class="eyebrow">LOCAL DATA & RESPONSIBILITY</p><h1>设置与关于</h1><p>数据、收藏和策略都保存在本机；LottoLab 不提供任何投注或售彩功能。</p></header><section class="grid"><article><h2>数据同步</h2><p>双色球与大乐透分别通过官方数据接口同步。同步失败时会继续使用本地缓存。</p><small>CSV格式：game, issue, draw_date, primary_numbers, secondary_numbers, sales_yuan, pool_yuan</small></article><article><h2>软件更新</h2><p>Windows 使用签名更新包；Android 仅检查公开版本并由系统浏览器下载安装包。</p><div class="actions"><button type="button" @click="checkUpdate">检查更新</button><button v-if="updateAction" type="button" @click="runUpdateAction">{{ actionLabel }}</button></div><small>{{ update }}</small></article><article><h2>责任提示</h2><p>历史评分不等于中奖概率。所有合法号码组合的理论中奖机会相同。</p><small>非官方产品，仅供统计研究；理性购彩，禁止未成年人购彩。</small></article><article><h2>版权说明</h2><p>LottoLab 源码公开于 LightyearXizIl/LottoLab，但保留全部权利，未授予开源许可证。</p><small>不使用任何福彩、体彩官方标识或服务。</small></article></section></div></template>
